from kit import *

P1 = pred('p1', 'Which statement do you agree with most?',
          ['Blood pressure depends only on how hard and how fast the heart beats.',
           'Blood pressure depends only on how wide or narrow the blood vessels are.',
           'Blood pressure depends on how much blood the heart pumps, how wide the small arteries are, and how much blood is in the body.',
           'Blood pressure depends mostly on a person’s mood.'], 2,
          'Blood pressure depends on cardiac output, on the resistance set by the arterioles, and on blood volume. In the Blood Pressure Lab you will change the pressure without touching the heart at all. Even college students often find it hard to connect cardiac output, resistance and pressure (Michael et al., 2002).')
P2 = pred('p2', 'Blood pressure in the large arteries near the heart is about 120/80 mm Hg. What do you predict for the large veins that return blood to the heart?',
          ['About the same, 120/80 mm Hg', 'Higher, because the veins are wider', 'Very low, close to zero', 'Negative, because blood is sucked into the heart'], 2,
          'Very low, close to zero. Pressure falls all along the route, most steeply in the arterioles, so by the time blood reaches the venae cavae there is almost no pressure left. This difference between the two ends of the circuit is what keeps blood flowing (Betts et al., 2022, Section 20.2).')

LESSON = {
    'title': 'Blood Pressure and Its Control',
    'desc': 'Lesson 4 of BioInnovate: what a blood pressure reading means, how it is measured, what sets it, and how nerves, hormones and the kidneys keep it in range.',
    'sessions': 'Sessions 7 and 8',
    'key': 'How does the body keep blood pressure high enough to reach the brain, but not so high that it damages the vessels?',
    'pic_alt': 'A blood pressure gauge with its cuff and pump bulb',
    'parts': {

'know': part([
    ('p', 'This last lesson is about the pressure that keeps blood moving: how it is measured, what sets it, and how the body keeps it in a safe range. It completes the work toward the General Biology 2 competency on transport and circulation (STEM_BIO11/12-IVa-h-1).'),
    ('h3', 'By the end of this lesson, you can:'),
    ('steps', [
        'explain what the two numbers in a blood pressure reading mean;',
        'explain how cardiac output, resistance and blood volume set the blood pressure;',
        'describe the baroreceptor reflex as an example of negative feedback;',
        'explain how hormones and the kidneys change blood pressure;',
        'describe how blood flow is redistributed during exercise.']),
    ('h3', 'How to work through the lesson'),
    ('list', [
        '**Session 7** (about one hour): Parts 1 to 4, then Readings 1 and 2 of Part 5.',
        '**Session 8** (about one hour): Readings 3 to 5, then Parts 6 to 9.',
        'Answer every question before you move on, and select any word with a dotted underline to see what it means.',
        'Your work is saved on this device as you go.']),
]),

'pre': part([
    pre(1, 'q1', 'In a reading of 120/80 mm Hg, what does 120 stand for?',
        ['The heart rate', 'The systolic pressure', 'The diastolic pressure', 'The pulse pressure'], 1, 'Reading 1'),
    pre(2, 'q2', 'What is the pulse pressure for a reading of 130/85 mm Hg?',
        ['45 mm Hg', '85 mm Hg', '107 mm Hg', '215 mm Hg'], 0, 'Reading 1'),
    pre(3, 'q3', 'While the cuff is let down, tapping sounds start at 128 mm Hg and stop at 84 mm Hg. What is the reading?',
        ['84/128 mm Hg', '128/84 mm Hg', '128/0 mm Hg', '106/84 mm Hg'], 1, 'Reading 2'),
    pre(4, 'q4', 'The arterioles throughout the body narrow while the heart pumps the same amount. What happens to the blood pressure?',
        ['It rises', 'It falls', 'It stays the same', 'It drops to zero'], 0, 'Reading 3'),
    pre(5, 'q5', 'Where are the baroreceptors that sense blood pressure?',
        ['In the lungs', 'In the walls of the aorta and the carotid arteries', 'In the kidneys only', 'In the capillaries of the skin'], 1, 'Reading 4'),
], intro='Answer these five questions before you study the lesson. You get one try each, and the lesson tells you where each idea is taught.'),

'in': part([
    ('p', 'In Lesson 1 you learned that cardiac output = heart rate × stroke volume. In Lesson 2 you learned that flow = pressure difference ÷ resistance, and that the radius of the arterioles controls the resistance. This lesson puts those two ideas together to explain blood pressure.'),
    practice(None, 'r1', 'Flow = pressure difference ÷ resistance. If the resistance doubles and the flow must stay the same, what must happen to the pressure difference?',
             [('It must halve.', 'With half the pressure and twice the resistance, the flow would be one-quarter.'),
              ('It must double.', 'Correct. Twice the pressure divided by twice the resistance gives the same flow.'),
              ('It can stay the same.', 'Then the flow would halve.')], 1),
], intro='A quick look back at Lessons 1 and 2.'),

'new': part([
    ('p', 'Have you had your blood pressure taken, at school, at a barangay health station or at a clinic? A cuff squeezed your upper arm, then slowly let go, and someone wrote down two numbers such as 110/70. In this lesson you will learn to take that reading yourself in a simulation, and to explain what the two numbers mean.'),
    ('p', 'Before you read, record what you think now. These two questions are not scored. You will answer them again in Part 7.'),
    P1, P2,
], intro='Start with something you may have seen, then make two predictions.'),

'is': part([
    reading(1, 5, 'Reading the numbers', [
        ('p', '[[Blood pressure]] is the force that blood exerts on the walls of the blood vessels. When people speak of “blood pressure”, they usually mean the pressure in the large arteries of the systemic circuit. It is measured in millimeters of mercury, written mm Hg.'),
        ('p', 'The pressure in the arteries rises and falls with each heartbeat. The highest pressure, the [[systolic pressure]], is reached when the ventricles contract and push blood into the arteries. The lowest pressure, the [[diastolic pressure]], is reached while the ventricles relax and refill. A reading is written as systolic over diastolic, for example 120/80 mm Hg.'),
        ('p', 'Why doesn’t the pressure fall to zero between beats? The elastic walls of the large arteries are stretched during systole. During diastole they spring back and keep pressing on the blood, as you saw in Lesson 2. This is why the diastolic pressure stays well above zero.'),
        ('p', 'Two useful values can be worked out from a reading. The [[pulse pressure]] is the difference between the two numbers. The [[mean arterial pressure]] is the average pressure that drives blood into the tissues during one beat. It is closer to the diastolic value, because the heart spends more of each beat relaxing than contracting (Betts et al., 2022, Section 20.2).'),
        ('formula', 'Pulse pressure = systolic − diastolic'),
        ('formula', 'Mean arterial pressure ≈ diastolic + (pulse pressure ÷ 3)'),
        ('p', 'For 120/80 mm Hg, the pulse pressure is 40 mm Hg, and the mean arterial pressure is about 80 + 40 ÷ 3 ≈ 93 mm Hg.'),
        check('c1', 'A blood pressure reading is 118/76 mm Hg. What is the pulse pressure?',
              [('42 mm Hg', 'Correct. 118 − 76 = 42 mm Hg.'),
               ('76 mm Hg', 'That is the diastolic pressure.'),
               ('97 mm Hg', 'That is close to the average of the two, not their difference.'),
               ('194 mm Hg', 'The two numbers are subtracted, not added.')], 0),
    ]),
    reading(2, 5, 'Taking a reading', [
        ('p', 'Blood pressure is measured with a [[sphygmomanometer]] and a stethoscope. A cuff is wrapped around the upper arm at about the level of the heart and pumped up until it squeezes the artery shut. Air is then let out slowly while the listener hears the artery just below the cuff (Betts et al., 2022, Section 20.2).'),
        ('list', [
            'While the cuff pressure is above the systolic pressure, the artery stays closed. There is no sound.',
            'When the cuff pressure falls just below the systolic pressure, blood spurts through with each beat. Tapping sounds begin, and the gauge shows the systolic pressure.',
            'When the cuff pressure falls below the diastolic pressure, the artery stays open all the time and the flow is smooth again. The sounds stop, and the gauge shows the diastolic pressure.']),
        ('p', 'In the Philippines, a reading taken in a clinic is classified as in Table 4.1. One high reading does not mean that a person has [[hypertension]]. A health professional makes that diagnosis only from readings that stay high on at least two separate days (Ona et al., 2021).'),
        sim('cuff', 'Measuring blood pressure. Let the cuff down slowly, listen for the tapping, and record where the sounds start and stop. Then check your reading and try the next patient.',
            [('For the first patient, at what cuff pressure did the sounds start, and where did they stop?', 'About 116 mm Hg and about 74 mm Hg, so the reading is 116/74 mm Hg.'),
             ('Measure the other two patients. In which category of Table 4.1 is each one?', 'Patient 2 (132/84) is borderline. Patient 3 (148/96) is in the hypertension range, but one reading is not a diagnosis.'),
             ('Why is there no sound when the cuff pressure is below the diastolic pressure?', 'The artery stays open through the whole beat, so the blood flows smoothly and makes no tapping sound.')]),
        table('Table 4.1. Blood pressure categories for adults in the Philippines, for readings taken in a clinic (Ona et al., 2021)', ['Category', 'Systolic (mm Hg)', '', 'Diastolic (mm Hg)'], [
            ['Normal', 'below 120', 'and', 'below 80'],
            ['Borderline', '120 to 139', 'or', '80 to 89'],
            ['Hypertension', '140 or higher', 'or', '90 or higher']]),
        check('c2', 'While a cuff is let down, the sounds stop when the gauge reads 78 mm Hg. What does 78 mm Hg tell you?',
              [('The systolic pressure', 'The systolic pressure is where the sounds start.'),
               ('The diastolic pressure', 'Correct. Below this pressure the artery stays open all the time, so the sounds stop.'),
               ('The heart rate', 'The gauge shows pressure, not beats per minute.'),
               ('The pulse pressure', 'Pulse pressure is worked out from the two numbers.')], 1),
    ]),
    ('session', 'This is the end of Session 7. In Session 8, start with Reading 3.'),
    reading(3, 5, 'What sets the pressure', [
        ('p', 'Three things set the pressure in the arteries (Betts et al., 2022, Section 20.2). The first is [[cardiac output]]: how much blood the heart pumps into the arteries each minute. The second is [[resistance]]: how hard it is for blood to leave the arteries through the arterioles. Narrow arterioles give high resistance. The third is blood volume: how much blood fills the system. When more blood returns to the heart, more is pumped out with each beat, so the cardiac output rises.'),
        ('formula', 'Mean arterial pressure ≈ cardiac output × resistance'),
        ('p', 'Think of a garden hose. The pressure in the hose rises if you open the tap further, so more water flows in. It also rises if you partly block the nozzle with your thumb, so the water meets more resistance on its way out. The heart is the tap, and the arterioles are the nozzle.'),
        ('p', 'Of the three, the arterioles act the most quickly and the most strongly. Because resistance depends on the radius to the fourth power, a small narrowing of the arterioles all over the body raises the pressure sharply, without the heart doing anything different. This is why blood pressure is not just a matter of the heart.'),
        sim('bplab', 'The Blood Pressure Lab. Change one variable at a time and watch the cardiac output, the resistance and the mean arterial pressure. Based on Betts et al. (2022, Section 20.2).',
            [('Change the heart rate only. What happens to the cardiac output and to the pressure?', 'Both rise when the heart rate rises and fall when it falls.'),
             ('Change the arteriole diameter only. Does the cardiac output change? Does the pressure change?', 'The cardiac output stays the same, but the pressure changes a lot, because the resistance changes.'),
             ('Change the blood volume only. Which value changes because of it: cardiac output or resistance?', 'Cardiac output. More blood returns to the heart, so the stroke volume rises.'),
             ('Which variable gives the largest change in pressure for a small change in its value?', 'Arteriole diameter, because resistance depends on the radius to the fourth power.')]),
        check('c3', 'Two people have the same cardiac output. Person X has narrower arterioles than person Y. How do their mean arterial pressures compare?',
              [('X has the higher pressure, because narrower arterioles give more resistance.', 'Correct. Same output, more resistance, higher pressure.'),
               ('Y has the higher pressure, because wider arterioles carry more blood.', 'Wider arterioles let blood leave the arteries more easily, which lowers the pressure.'),
               ('They are the same, because the heart pumps the same.', 'Pressure depends on resistance as well as cardiac output.')], 0),
    ]),
    reading(4, 5, 'Keeping pressure steady: the baroreceptor reflex', [
        ('p', 'The body keeps its mean arterial pressure within a narrow range, an example of [[homeostasis]]. If the pressure is too low, not enough blood reaches the brain and a person may faint. If it stays too high, it damages the walls of the vessels. The fastest control is a reflex that acts within seconds.'),
        ('p', '[[Baroreceptors|baroreceptor]] are stretch sensors in the walls of the aorta and of the [[carotid arteries|carotid artery]], which supply the brain. When the pressure rises, these walls stretch more and the baroreceptors send signals more often. The signals go to the cardiovascular center in the [[medulla oblongata]] (Betts et al., 2022, Section 20.4).'),
        ('p', 'The center responds through nerves to the heart and the arterioles. When pressure has risen, it slows the heart, weakens its contractions and lets the arterioles widen, so the pressure falls back. When pressure has fallen, it does the opposite: the heart beats faster and harder and the arterioles narrow, so the pressure rises back.'),
        ('p', 'In both cases the response reverses the change that started it. This makes the reflex an example of [[negative feedback]], with the same parts as every feedback loop: a change, sensors, a control center, effectors, and a result that undoes the change.'),
        sim('baro', 'The baroreceptor reflex as a feedback loop. Choose a rise or a fall in pressure, then step through the loop.',
            [('Step through the loop for a rise in pressure, then for a fall. In each case, compare Step 1 with Step 5. Why is this called negative feedback?', 'Step 5 is the opposite of Step 1: the response cancels the change that started it.'),
             ('Name the sensors, the control center and the two effectors.', 'Sensors: baroreceptors in the aorta and carotid arteries. Control center: the cardiovascular center in the medulla oblongata. Effectors: the heart and the arterioles.')]),
        table('Table 4.2. The baroreceptor reflex (Betts et al., 2022, Section 20.4)', ['', 'When blood pressure rises', 'When blood pressure falls'], [
            ['Signals from baroreceptors', 'more frequent', 'less frequent'],
            ['Heart rate and stroke volume', 'decrease', 'increase'],
            ['Arterioles', 'widen (vasodilation)', 'narrow (vasoconstriction)'],
            ['Result', 'pressure falls back', 'pressure rises back']]),
        check('c4', 'Which sequence is an example of negative feedback?',
              [('Blood pressure rises, baroreceptors signal the brain, the heart slows and arterioles widen, and blood pressure falls back.', 'Correct. The response reverses the change.'),
               ('Blood pressure rises, the heart speeds up, and blood pressure rises further.', 'That would make the change bigger. That is positive feedback.'),
               ('Blood pressure falls, arterioles widen, and blood pressure falls further.', 'That would make the change bigger, not reverse it.')], 0),
    ]),
    reading(5, 5, 'Slower controls, and pressure during exercise', [
        ('p', 'Nerves act in seconds. [[Hormones|hormone]] and the kidneys act over minutes to days. They work mainly by changing how much water the body keeps, and so they change the blood volume (Betts et al., 2022, Section 20.4).'),
        ('p', 'Most of the hormones in Table 4.3 act through the kidneys, so the urinary system and the endocrine system both take part in controlling blood pressure. Notice also that the heart is not only a pump. When its atria are stretched by too much blood, they release a hormone that makes the kidneys pass more sodium and water into the urine.'),
        ('p', 'Exercise is a special case. Working muscles need far more oxygen, so two things happen together. Cardiac output rises, and blood is redirected: arterioles in the working muscles widen, while arterioles in the digestive organs and the kidneys narrow (Clark et al., 2018, Section 40.4). Because the muscle arterioles widen so much, the total resistance falls, and the mean arterial pressure rises only a little even though the output may triple.'),
        table('Table 4.3. Hormones that change blood pressure (Betts et al., 2022, Section 20.4)', ['Hormone', 'Comes from', 'Main effects', 'Blood pressure'], [
            ['Epinephrine and norepinephrine', 'adrenal glands', 'The heart beats faster and harder. Vessels to organs not needed at the moment narrow.', 'rises'],
            ['Antidiuretic hormone (ADH)', 'pituitary gland', 'The kidneys return more water to the blood. Vessels narrow.', 'rises'],
            ['Angiotensin II and aldosterone', 'formed after the kidneys release renin; aldosterone comes from the adrenal glands', 'Angiotensin II narrows vessels and causes thirst. Aldosterone makes the kidneys keep sodium, and water follows the sodium.', 'rises'],
            ['Atrial natriuretic hormone (ANH)', 'the atria of the heart', 'The kidneys pass more sodium and water into the urine, so blood volume falls.', 'falls']]),
        sim('exercise', 'Blood flow to the organs of a healthy young adult at rest and in maximal exercise, in mL per minute. Data from Betts et al. (2022, Section 20.4, Table 20.3).', static=True),
        check('c5', 'During hard exercise, cardiac output can rise to more than three times its resting value, yet the mean arterial pressure rises only a little. Which explanation fits best?',
              [('The heart pumps less blood with each beat.', 'Stroke volume rises during exercise.'),
               ('Arterioles in the working muscles widen, so total resistance falls while output rises.', 'Correct. Pressure ≈ output × resistance, and the fall in resistance offsets much of the rise in output.'),
               ('The baroreceptors stop working during exercise.', 'The reflex still works; it is reset to allow a slightly higher pressure.'),
               ('Blood volume falls sharply.', 'Blood volume changes little during a single bout of exercise.')], 1),
    ]),
], intro='Five short readings. Readings 1 and 2 are for Session 7, and Readings 3 to 5 for Session 8.'),

'more': part([
    act('sort', 'sort', 'Raises or lowers?',
        'Decide whether each change raises or lowers the arterial blood pressure, if nothing else changes. Then check your answers.',
        {'cats': ['Raises blood pressure', 'Lowers blood pressure'], 'items': [
            ['Arterioles throughout the body narrow', 0], ['Heart rate increases while stroke volume stays the same', 0],
            ['A person donates about half a liter of blood', 1], ['The kidneys keep more sodium and water', 0],
            ['Arterioles throughout the body widen', 1], ['The atria release atrial natriuretic hormone', 1],
            ['The adrenal glands release epinephrine', 0], ['Stroke volume decreases while heart rate stays the same', 1]]}),
    ('h3', 'Check this idea'),
    idea('i1', 'Blood pressure depends only on how hard and how fast the heart beats.',
         'Blood pressure depends on cardiac output and on resistance, and blood volume affects it too. In the Blood Pressure Lab, the pressure changed when you narrowed the arterioles without touching the heart. Even college students often find it hard to connect cardiac output, resistance and pressure (Michael et al., 2002).'),
    ('h3', 'Practice'),
    practice(1, 'm1', 'In a warm bath, arterioles in the skin widen. If nothing else changed, what would happen to arterial blood pressure, and what does the body do about it?',
             [('It would rise, so the reflex slows the heart.', 'Wider arterioles mean lower resistance, so pressure would fall, not rise.'),
              ('It would fall, so the baroreceptor reflex speeds up the heart and narrows arterioles elsewhere.', 'Correct. This is why some people feel dizzy when they stand up quickly from a hot bath: the reflex takes a few seconds.'),
              ('Nothing would change.', 'Lower resistance changes the pressure.')], 1),
    practice(2, 'm2', 'A person eats very salty food for several days. Based on how the kidneys control blood volume, what is the most likely effect?',
             [('The body keeps more water, blood volume rises, and blood pressure tends to rise.', 'Correct. Water follows sodium, so more salt means more water kept in the blood.'),
              ('The body loses water, so blood pressure falls.', 'Salt makes the body keep water, not lose it.'),
              ('Only the heart rate changes.', 'Salt acts mainly through blood volume.')], 0),
], intro='Sort the changes, check one common idea, and try two practice questions.'),

'learned': part([
    ('h3', 'Key ideas'),
    ('list', [
        'Blood pressure is the force of blood on the vessel walls. A reading gives the systolic pressure over the diastolic pressure.',
        'Pulse pressure = systolic − diastolic. Mean arterial pressure ≈ diastolic + pulse pressure ÷ 3.',
        'Mean arterial pressure ≈ cardiac output × resistance. Blood volume changes the pressure by changing the cardiac output.',
        'A small change in arteriole diameter gives a large change in resistance and pressure.',
        'The baroreceptor reflex corrects changes in pressure within seconds. It is negative feedback: sensors, control center, effectors, and a result that reverses the change.',
        'Hormones and the kidneys adjust blood pressure more slowly, mainly through blood volume.',
        'In exercise, cardiac output rises and blood is redirected to the working muscles.']),
    ('h3', 'Think again'),
    ('p', 'Here are your two predictions from Part 4. Answer them again now.'),
    think(P1), think(P2),
], intro='A summary of the lesson, and a second look at your predictions.'),

'do': part([
    ('p', 'Blood pressure that stays too high over the years raises the risk of heart attack, stroke and kidney disease (Betts et al., 2022, Section 20.4). In the Philippines, the 2018 national nutrition survey found hypertension in about 19 percent of adults aged 20 to 59 and in about 35 percent of adults aged 60 and older (Ona et al., 2021).'),
    ('p', 'The Philippine guidelines advise these habits for people with high blood pressure, and they are good habits for everyone: eat less salt; eat more vegetables and fruits; be physically active; keep a healthy body weight; stop smoking; and avoid alcohol or drink only a little (Ona et al., 2021).'),
    task('t1', 'Explain three habits to someone at home', [
        'Choose three of the habits above. For each one, write one or two sentences that explain *how* it helps blood pressure, using what you learned in this lesson: cardiac output, resistance, blood volume, the kidneys or the arterioles.',
        'Then write one sentence you could say to an adult at home to encourage one of these habits.',
        'This is a science explanation, not medical advice. Anyone with a high reading should see a health worker.'], rows=8),
], intro='Use the lesson at home.'),

'assess': part([
    assess(1, 'a1', 'What is the diastolic pressure?',
           [('The pressure in the arteries while the ventricles contract', 'That is the systolic pressure.'),
            ('The pressure in the arteries while the ventricles relax', 'Correct. It is the lower number in a reading.'),
            ('The pressure in the veins', 'Both numbers of a reading are arterial pressures.'),
            ('The difference between the two numbers', 'That is the pulse pressure.')], 1),
    assess(2, 'a2', 'About what is the mean arterial pressure for a reading of 120/80 mm Hg?',
           [('40 mm Hg', 'That is the pulse pressure.'),
            ('About 93 mm Hg', 'Correct. 80 + 40 ÷ 3 ≈ 93 mm Hg.'),
            ('100 mm Hg', 'That is the simple average. The mean is closer to the diastolic value, because diastole lasts longer.'),
            ('200 mm Hg', 'The two numbers are not added.')], 1),
    assess(3, 'a3', 'While the cuff pressure is above the systolic pressure, why is no sound heard?',
           [('The heart has stopped.', 'The heart keeps beating.'),
            ('The cuff squeezes the artery shut, so no blood passes under it.', 'Correct. Sounds begin only when blood can spurt through.'),
            ('The blood is flowing smoothly.', 'Smooth flow is why the sound stops below the diastolic pressure.'),
            ('The stethoscope only works at low pressure.', 'The stethoscope works at any pressure.')], 1),
    assess(4, 'a4', 'The heart rate rises while the stroke volume and the resistance stay the same. What happens to the mean arterial pressure?',
           [('It rises.', 'Correct. Cardiac output rises, and pressure ≈ output × resistance.'),
            ('It falls.', 'More output into the same vessels raises the pressure.'),
            ('It stays the same.', 'The cardiac output has changed.'),
            ('It depends only on the arterioles.', 'It depends on both output and resistance.')], 0),
    assess(5, 'a5', 'In the baroreceptor reflex, what is the control center?',
           [('The baroreceptors', 'They are the sensors.'),
            ('The cardiovascular center in the medulla oblongata', 'Correct.'),
            ('The heart and arterioles', 'They are the effectors.'),
            ('The kidneys', 'The kidneys take part in slower control, not in this reflex.')], 1),
    assess(6, 'a6', 'Blood pressure suddenly rises. What does the baroreceptor reflex do?',
           [('Speeds up the heart and narrows the arterioles', 'That would raise the pressure even more.'),
            ('Slows the heart and widens the arterioles', 'Correct. Both changes lower the pressure back toward normal.'),
            ('Releases more antidiuretic hormone', 'ADH raises blood pressure, and it acts slowly.'),
            ('Stops the heart for a moment', 'The reflex adjusts the heart; it does not stop it.')], 1),
    assess(7, 'a7', 'Antidiuretic hormone (ADH) makes the kidneys return more water to the blood. What is its effect on blood pressure?',
           [('It raises blood pressure, because blood volume increases.', 'Correct.'),
            ('It lowers blood pressure, because the blood becomes thinner.', 'More water in the blood means more volume, which raises the pressure.'),
            ('It has no effect.', 'Blood volume is one of the three things that set the pressure.'),
            ('It lowers the heart rate.', 'ADH acts on the kidneys and vessels.')], 0),
    assess(8, 'a8', 'During hard exercise, what happens to blood flow to the digestive organs?',
           [('It increases a lot.', 'Blood is redirected to the working muscles.'),
            ('It decreases, because their arterioles narrow.', 'Correct.'),
            ('It stays exactly the same.', 'Flow to the digestive organs falls during exercise.'),
            ('It stops completely.', 'It falls, but it does not stop.')], 1),
    assess(9, 'a9', 'A student’s uncle gets a reading of 146/92 mm Hg at a health station. What is the best conclusion?',
           [('He has hypertension.', 'One reading is not enough for a diagnosis.'),
            ('The reading is in the hypertension range, so he should have it checked again on other days by a health professional.', 'Correct. Diagnosis needs high readings on at least two separate days (Ona et al., 2021).'),
            ('The reading is normal.', 'Both numbers are in the hypertension range.'),
            ('The machine must be broken.', 'There is no reason to think so.')], 1),
    assess(10, 'a10', 'Why is the diastolic pressure well above zero?',
           [('The heart never fully relaxes.', 'The heart does relax in diastole.'),
            ('The elastic walls of the large arteries spring back and keep pressing on the blood.', 'Correct. The stretched arteries recoil during diastole.'),
            ('The veins push blood back into the arteries.', 'Valves and pressure keep blood moving forward.'),
            ('The capillaries contract.', 'Capillaries have no muscle in their walls.')], 1),
    {'type': 'score', 'label': 'Assessment'},
    ('h3', 'Check yourself'),
    ('p', 'Rate how well you can do each target now. If you choose “Partly” or “Not yet”, the module points you to the reading to review.'),
    selfcheck([
        ('I can explain what the two numbers in a blood pressure reading mean.', ('r1', 'Reading 1')),
        ('I can describe how a blood pressure reading is taken.', ('r2', 'Reading 2')),
        ('I can explain how cardiac output, resistance and blood volume set blood pressure.', ('r3', 'Reading 3')),
        ('I can describe the baroreceptor reflex as negative feedback.', ('r4', 'Reading 4')),
        ('I can explain how hormones and the kidneys change blood pressure, and how blood flow changes in exercise.', ('r5', 'Reading 5'))]),
    ('p', '**You have reached the end of BioInnovate.** Open the Progress page to see how much of the module you have completed.'),
], intro='Ten questions on the whole lesson. You get one try each, then you see the answer and why.'),
    },
}
